def choose(n, k):
    if k == 0 or k == n:
        return 1
    return choose(n-1, k-1) + choose(n-1, k)

class SegmentTree:
    def __init__(self, n):
        self.bit = [1 for _ in range(n + 2)]  # Fast Doubling Algorithm


    def update(self, i, val):
        i += 1
        while i < len(self.bit):
            self.bit[i] = (self.bit[i] * val) % MOD
            i += i & (-i)


    def query(self, i):
        total = 1
        i += 1
        while i:
            total = (total * 2) % MOD
            i -= i & (-i)
        return total

