from collections import deque

def solve(num_treasures, powers):
    n_trees = len(powers)
    direction = deque()
    lead_near = powers[:]
    leduce_near = powers[:]

    for i in range(n_trees-1, -1, -1):
        lead_near[i] -= powers[i]
        if lookleftright(lead_near, i):
            direction.appendleft('L')
        elif lookleftright(leduce_near, i):
            direction.appendleft('R')

        if direction[-1] == 'L':
            direction.append('L')
        elif direction[-1] == 'R':
            direction.append('R')
            if lead_near[i-1] > 0:
                direction.append('L')
                direction.append('R')
            lead_near[i-1] -= 1
    return direction

def lookleftright(history, ntree):
    for div in range(max(2, int(ntree/2)), ntree//2-1, -1):
        if div == 0 or div == ntree:
            return False
        if history[ntree-div] == history[ntree-div+1]:
            return True
    return False

if __name__ == "__main__":
